import{_ as s,o as e,c as t,a2 as i}from"./chunks/framework.DbKnw1Aw.js";const k=JSON.parse('{"title":"策略组","description":"","frontmatter":{},"headers":[],"relativePath":"guide/groups.md","filePath":"guide/groups.md","lastUpdated":1794385075000}'),n={name:"guide/groups.md"};function d(l,a,o,p,c,h){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="策略组" tabindex="-1">策略组 <a class="header-anchor" href="#策略组" aria-label="Permalink to &quot;策略组&quot;">​</a></h1><h2 id="三层结构" tabindex="-1">三层结构 <a class="header-anchor" href="#三层结构" aria-label="Permalink to &quot;三层结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规则命中</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>业务组（🌐 非中国、🔍 谷歌服务、🐟 漏网之鱼……）   select，手动选择</span></span>
<span class="line"><span>  ↓ 默认选 🚀 节点选择</span></span>
<span class="line"><span>🚀 节点选择                                      select，总开关</span></span>
<span class="line"><span>  ↓ 默认选 ⚡ 自动选择</span></span>
<span class="line"><span>⚡ 自动选择                                      url-test，自动测速</span></span>
<span class="line"><span>  ↓ 选延迟最低的节点</span></span>
<span class="line"><span>具体节点</span></span></code></pre></div><p>这样设计的好处是：只切换 <code>🚀 节点选择</code> 就能控制大部分流量；某类流量需要例外时（例如流媒体只能用某个地区的节点），单独切换对应的业务组即可。</p><h2 id="⚡-自动选择" tabindex="-1">⚡ 自动选择 <a class="header-anchor" href="#⚡-自动选择" aria-label="Permalink to &quot;⚡ 自动选择&quot;">​</a></h2><p>成员只有节点，不包含 <code>DIRECT</code> / <code>REJECT</code>。Clash 配置中：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">⚡ 自动选择</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">url-test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://www.gstatic.com/generate_204</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  interval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  lazy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>客户端每隔 300 秒通过每个节点请求一次测速地址，自动使用延迟最低的节点；超时的节点不会被选中。<code>lazy: false</code> 表示即使当前没有流量使用该组，也照常测速。sing-box 中使用 <code>urltest</code> 出站，测速参数采用 sing-box 的默认值。</p><p>注意测的是到测速地址的延迟，不代表带宽，也不代表访问其他网站的速度。</p><h2 id="🚀-节点选择" tabindex="-1">🚀 节点选择 <a class="header-anchor" href="#🚀-节点选择" aria-label="Permalink to &quot;🚀 节点选择&quot;">​</a></h2><p>成员依次为 <code>⚡ 自动选择</code>（默认）、<code>DIRECT</code> 和所有节点。选择具体节点表示固定使用它，选择 <code>DIRECT</code> 相当于让所有跟随它的流量直连。</p><h2 id="业务组的成员" tabindex="-1">业务组的成员 <a class="header-anchor" href="#业务组的成员" aria-label="Permalink to &quot;业务组的成员&quot;">​</a></h2><table tabindex="0"><thead><tr><th>业务组</th><th>成员（第一项为默认）</th></tr></thead><tbody><tr><td>一般分类（AI、谷歌、非中国等）</td><td><code>🚀 节点选择</code>、<code>DIRECT</code>、<code>⚡ 自动选择</code>、所有节点</td></tr><tr><td>私有网络、国内服务、苹果、微软</td><td><code>DIRECT</code>、<code>🚀 节点选择</code>、<code>⚡ 自动选择</code>、所有节点</td></tr><tr><td>广告拦截</td><td><code>REJECT</code>、<code>🚀 节点选择</code>、<code>DIRECT</code>、<code>⚡ 自动选择</code>、所有节点</td></tr><tr><td>高级规则中的自定义出站</td><td><code>🚀 节点选择</code>、<code>DIRECT</code>、<code>REJECT</code>、<code>⚡ 自动选择</code>、所有节点</td></tr><tr><td><code>🐟 漏网之鱼</code></td><td><code>🚀 节点选择</code>、<code>DIRECT</code>、<code>⚡ 自动选择</code>、所有节点</td></tr></tbody></table><p><code>REJECT</code> 只出现在广告拦截和自定义出站组中，其他组不提供拒绝选项，避免误选导致断网。sing-box 额外生成一个 <code>GLOBAL</code> 组，供&quot;全局模式&quot;使用，成员与 <code>🐟 漏网之鱼</code> 相同。</p><h2 id="手动选择会被记住吗" tabindex="-1">手动选择会被记住吗 <a class="header-anchor" href="#手动选择会被记住吗" aria-label="Permalink to &quot;手动选择会被记住吗&quot;">​</a></h2><p>取决于客户端设置：</p><ul><li>Clash 系客户端：配置项 <code>profile.store-selected</code> 为 <code>true</code> 时记住选择，否则重启后回到默认项（FlClash 等客户端可在设置中开启）。</li><li>sing-box：本项目生成的配置开启了 <code>cache_file</code>，会记住上次的选择。因此修改默认项后，已手动选择过的组不会自动变化，需要在客户端里手动切换一次。</li></ul>`,17)])])}const E=s(n,[["render",d]]);export{k as __pageData,E as default};
